// npm install puppeteer-core
const puppeteer = require("puppeteer-core");

(async () => {
  const url = process.argv[2] || "https://favisionenterprize.github.io/";
  const browser = await puppeteer.connect({ browserURL: "http://127.0.0.1:9222", defaultViewport: null });
  const page = await browser.newPage();
  await page.goto(url, { waitUntil: "networkidle2" });
  await page.pdf({ path: "page.pdf", format: "A4", printBackground: true });
  console.log("Saved page.pdf");
  await page.close();
  browser.disconnect();
})();

const rows = [...document.querySelectorAll("a[href]")]
  .map(a => [(a.innerText || a.title || "").trim().replace(/\s+/g, " "), a.href])
  .filter((r, i, all) => all.findIndex(x => x[1] === r[1]) === i);
const csv = [["text", "url"], ...rows].map(r => r.map(v => '"' + String(v).replace(/"/g, '""') + '"').join(",")).join("\n");
const a = document.createElement("a");
a.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
a.download = "links.csv";
a.click();
`${rows.length} links saved to links.csv`;

const tables = [...document.querySelectorAll("table")];
tables.forEach((t, n) => {
  const csv = [...t.rows].map(r => [...r.cells].map(c => '"' + c.innerText.trim().replace(/"/g, '""') + '"').join(",")).join("\n");
  const a = document.createElement("a");
  a.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
  a.download = `table-${n + 1}.csv`;
  a.click();
});
tables.length ? `${tables.length} table(s) downloaded` : "No tables on this page.";

(async () => {
  const end = Date.now() + 180000;
  let last = 0, same = 0;
  while (Date.now() < end && same < 4) {
    window.scrollTo(0, document.body.scrollHeight);
    await new Promise(r => setTimeout(r, 1800));
    const h = document.body.scrollHeight;
    same = h === last ? same + 1 : 0;
    last = h;
  }
  console.log("FA Vision: reached the end of the page");
})();
"Scrolling… it stops by itself when nothing new loads.";

const re = /^(see more|read more|show more|view more comments|view more replies)$/i;
let n = 0;
document.querySelectorAll("[role=button], button, span, a").forEach(el => {
  if (el.getClientRects().length && re.test((el.innerText || "").trim())) { el.click(); n++; }
});
`Opened ${n} "see more" button(s)`;

const rows = [];
document.querySelectorAll("[role=main] *").forEach(el => {
  if (el.children.length) return;
  const t = (el.innerText || "").trim();
  if (!/^(GH₵|GHS|₵)\s?[\d,]+/.test(t)) return;
  let box = el;
  for (let i = 0; i < 6 && box.parentElement; i++) box = box.parentElement;
  const lines = (box.innerText || "").split("\n").map(s => s.trim()).filter(Boolean);
  const title = lines.find(s => s !== t && !/^(GH₵|GHS|₵)/.test(s) && s.length > 3) || "";
  rows.push([title, t]);
});
const uniq = rows.filter((r, i) => rows.findIndex(x => x[0] === r[0] && x[1] === r[1]) === i);
const csv = [["title", "price"], ...uniq].map(r => r.map(v => '"' + v.replace(/"/g, '""') + '"').join(",")).join("\n");
const a = document.createElement("a");
a.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
a.download = "marketplace.csv";
a.click();
`${uniq.length} listings saved to marketplace.csv`;

const WORD = "sofa";   // change this
const re = new RegExp(WORD.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "gi");
let n = 0;
const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
const hits = [];
while (walk.nextNode()) { const node = walk.currentNode; if (node.parentElement && !/SCRIPT|STYLE/.test(node.parentElement.tagName) && re.test(node.nodeValue)) hits.push(node); re.lastIndex = 0; }
hits.forEach(node => {
  const span = document.createElement("span");
  span.innerHTML = node.nodeValue.replace(/[&<>]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c])).replace(re, m => { n++; return `<mark style="background:#ffe066">${m}</mark>`; });
  node.replaceWith(span);
});
`"${WORD}" found ${n} time(s)`;

const imgs = [...document.images]
  .filter(i => i.naturalWidth >= 200)
  .sort((a, b) => b.naturalWidth * b.naturalHeight - a.naturalWidth * a.naturalHeight)
  .map(i => i.currentSrc || i.src)
  .filter((u, i, all) => u && all.indexOf(u) === i);
const a = document.createElement("a");
a.href = URL.createObjectURL(new Blob([imgs.join("\n")], { type: "text/plain" }));
a.download = "images.txt";
a.click();
`${imgs.length} image addresses saved to images.txt`;

let n = 0;
document.querySelectorAll("body *").forEach(el => {
  const s = getComputedStyle(el);
  if ((s.position === "fixed" || s.position === "sticky") && el.offsetWidth * el.offsetHeight > innerWidth * innerHeight * 0.3) { el.style.display = "none"; n++; }
});
[document.documentElement, document.body].forEach(e => { e.style.overflow = "auto"; });
`Removed ${n} overlay(s)`;

# pip install requests
import requests

SITE = "https://favisionenterprize.github.io/"
data = requests.get(SITE + "data/products.json", timeout=30).json()
products = data.get("products", data) if isinstance(data, dict) else data

bad = []
for p in products:
    if p.get("placeholder"):
        continue
    urls = [SITE + "p/" + p["id"] + ".html"] + [SITE + i.lstrip("/") for i in p.get("images", [])[:3]]
    for u in urls:
        r = requests.head(u, timeout=20, allow_redirects=True)
        if r.status_code >= 400:
            bad.append((p["id"], u, r.status_code))

print(f"Checked {len(products)} products.")
for row in bad:
    print("BROKEN:", *row)
if not bad:
    print("Everything is online.")

// npm install puppeteer-core
const puppeteer = require("puppeteer-core");

const [url, selector = "body"] = process.argv.slice(2);
if (!url) { console.log("Usage: node watch.js URL [CSS selector]"); process.exit(1); }

(async () => {
  const browser = await puppeteer.connect({ browserURL: "http://127.0.0.1:9222", defaultViewport: null });
  const page = await browser.newPage();
  let last = null;
  for (;;) {
    await page.goto(url, { waitUntil: "networkidle2" });
    const now = await page.$eval(selector, el => el.innerText.trim()).catch(() => "(not found)");
    if (last !== null && now !== last) {
      process.stdout.write("\x07");
      console.log(new Date().toLocaleString(), "CHANGED:", last, "->", now);
    } else console.log(new Date().toLocaleTimeString(), now.slice(0, 80));
    last = now;
    await new Promise(r => setTimeout(r, 10 * 60 * 1000));
  }
})();
